package org.tabata.timber.core.timer

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertNotNull
import kotlin.test.assertTrue
import kotlinx.coroutines.test.runTest
import org.tabata.timber.domain.models.TimerState
import org.tabata.timber.domain.models.timer.PhaseType
import org.tabata.timber.domain.models.timer.TimerConfiguration

/**
 * Integration tests for PreciseTimerEngine
 * Uses MockPlatformTimer to control time and verify timing accuracy
 */
class PreciseTimerEngineTest {
    
    private class MockPlatformTimer : PlatformTimer {
        private var currentTimeNanos = 0L
        private var currentTimeMs = 0L
        private var timerCallback: (() -> Unit)? = null\n        private var _isRunning = false\n        \n        override val isRunning: Boolean get() = _isRunning\n        \n        override fun start(intervalMs: Long, callback: () -> Unit) {\n            timerCallback = callback\n            _isRunning = true\n        }\n        \n        override fun stop() {\n            _isRunning = false\n            timerCallback = null\n        }\n        \n        override fun getCurrentMonotonicTimeNanos(): Long = currentTimeNanos\n        \n        override fun getCurrentSystemTimeMs(): Long = currentTimeMs\n        \n        // Test control methods\n        fun advanceTimeMs(deltaMs: Long) {\n            currentTimeNanos += deltaMs * 1_000_000L\n            currentTimeMs += deltaMs\n        }\n        \n        fun triggerTimerTick() {\n            timerCallback?.invoke()\n        }\n        \n        fun reset() {\n            currentTimeNanos = 0L\n            currentTimeMs = 0L\n            _isRunning = false\n            timerCallback = null\n        }\n    }\n    \n    private fun createTestEngine(): Pair<PreciseTimerEngine, MockPlatformTimer> {\n        val mockTimer = MockPlatformTimer()\n        val engine = PreciseTimerEngine(mockTimer)\n        return Pair(engine, mockTimer)\n    }\n    \n    @Test\n    fun testInitialState() {\n        val (engine, _) = createTestEngine()\n        \n        assertEquals(TimerState.IDLE, engine.timerState.value)\n        assertEquals(PhaseType.WARMUP, engine.currentPhase.value)\n        assertFalse(engine.isActive.value)\n        assertEquals(0L, engine.remainingTimeMs.value)\n        assertEquals(0, engine.remainingTime.value)\n        assertEquals(0L, engine.elapsedTimeMs.value)\n        assertEquals(0, engine.currentCycle.value)\n        assertEquals(0, engine.currentSet.value)\n        assertNotNull(engine.precisionMetrics.value)\n    }\n    \n    @Test\n    fun testStartSessionSuccess() = runTest {\n        val (engine, mockTimer) = createTestEngine()\n        val config = TimerConfiguration.createStandard()\n        \n        val result = engine.startSession(config)\n        \n        assertTrue(result.isSuccess)\n        assertTrue(engine.isActive.value)\n        assertEquals(TimerState.WORK, engine.timerState.value)\n        assertEquals(config, engine.currentConfiguration.value)\n        assertTrue(mockTimer.isRunning)\n        assertNotNull(engine.currentSession.value)\n    }\n    \n    @Test\n    fun testStartSessionInvalidConfiguration() = runTest {\n        val (engine, _) = createTestEngine()\n        val invalidConfig = TimerConfiguration(\n            workDuration = 0, // Invalid\n            restDuration = 10,\n            cycles = 1,\n            sets = 1,\n            setBreakDuration = 60\n        )\n        \n        val result = engine.startSession(invalidConfig)\n        \n        assertTrue(result.isFailure)\n        assertFalse(engine.isActive.value)\n        assertEquals(TimerState.IDLE, engine.timerState.value)\n    }\n    \n    @Test\n    fun testPauseAndResumeSession() = runTest {\n        val (engine, mockTimer) = createTestEngine()\n        val config = TimerConfiguration.createStandard()\n        \n        // Start session\n        engine.startSession(config)\n        assertTrue(engine.isActive.value)\n        \n        // Advance time and pause\n        mockTimer.advanceTimeMs(5000L) // 5 seconds\n        mockTimer.triggerTimerTick()\n        \n        val pauseResult = engine.pauseSession()\n        assertTrue(pauseResult.isSuccess)\n        assertEquals(TimerState.PAUSED, engine.timerState.value)\n        \n        // Advance time while paused\n        val elapsedBeforePause = engine.elapsedTimeMs.value\n        mockTimer.advanceTimeMs(3000L) // 3 more seconds while paused\n        mockTimer.triggerTimerTick()\n        \n        // Time should not advance while paused (in logic, but mock doesn't implement this)\n        // Resume session\n        val resumeResult = engine.resumeSession()\n        assertTrue(resumeResult.isSuccess)\n        assertTrue(engine.timerState.value != TimerState.PAUSED)\n    }\n    \n    @Test\n    fun testStopSession() = runTest {\n        val (engine, mockTimer) = createTestEngine()\n        val config = TimerConfiguration.createStandard()\n        \n        // Start session\n        engine.startSession(config)\n        assertTrue(engine.isActive.value)\n        \n        // Stop session\n        val result = engine.stopSession()\n        \n        assertTrue(result.isSuccess)\n        assertEquals(TimerState.IDLE, engine.timerState.value)\n        assertFalse(engine.isActive.value)\n        assertFalse(mockTimer.isRunning)\n        assertEquals(0L, engine.remainingTimeMs.value)\n        assertEquals(0L, engine.elapsedTimeMs.value)\n    }\n    \n    @Test\n    fun testSkipToNext() = runTest {\n        val (engine, mockTimer) = createTestEngine()\n        val config = TimerConfiguration(\n            workDuration = 10,\n            restDuration = 5,\n            cycles = 2,\n            sets = 1,\n            setBreakDuration = 0,\n            warmupDuration = 5,\n            cooldownDuration = 0\n        )\n        \n        // Start session (should be in warmup)\n        engine.startSession(config)\n        \n        // Should start in warmup, skip to work\n        val skipResult = engine.skipToNext()\n        assertTrue(skipResult.isSuccess)\n        \n        // Trigger timer tick to update state\n        mockTimer.triggerTimerTick()\n        \n        // Phase should have advanced (exact phase depends on implementation)\n        assertTrue(engine.isActive.value)\n    }\n    \n    @Test\n    fun testTimerPrecisionTracking() = runTest {\n        val (engine, mockTimer) = createTestEngine()\n        val config = TimerConfiguration.createStandard()\n        \n        engine.startSession(config)\n        \n        // Advance time and trigger multiple ticks\n        repeat(5) {\n            mockTimer.advanceTimeMs(50L) // 50ms intervals\n            mockTimer.triggerTimerTick()\n        }\n        \n        val metrics = engine.precisionMetrics.value\n        \n        // Should have some precision data\n        assertTrue(metrics.sampleCount >= 0)\n        assertNotNull(metrics.currentDriftMs)\n    }\n    \n    @Test\n    fun testPhaseTransitions() = runTest {\n        val (engine, mockTimer) = createTestEngine()\n        val config = TimerConfiguration(\n            workDuration = 2,  // 2 seconds\n            restDuration = 1,  // 1 second\n            cycles = 2,\n            sets = 1,\n            setBreakDuration = 0,\n            warmupDuration = 1, // 1 second warmup\n            cooldownDuration = 1 // 1 second cooldown\n        )\n        \n        engine.startSession(config)\n        \n        // Should start in warmup (or work, depending on implementation)\n        val initialPhase = engine.currentPhase.value\n        assertNotNull(initialPhase)\n        \n        // Advance through the entire session\n        var totalTimeMs = 0L\n        val phaseChanges = mutableListOf<PhaseType>()\n        \n        // Simulate running for total duration\n        val totalDurationMs = (1 + 2 + 1 + 2 + 1 + 1) * 1000L // 8 seconds total\n        while (totalTimeMs < totalDurationMs && engine.isActive.value) {\n            mockTimer.advanceTimeMs(100L) // Advance 100ms at a time\n            mockTimer.triggerTimerTick()\n            totalTimeMs += 100L\n            \n            val currentPhase = engine.currentPhase.value\n            if (phaseChanges.isEmpty() || phaseChanges.last() != currentPhase) {\n                phaseChanges.add(currentPhase)\n            }\n        }\n        \n        // Should have seen multiple phases\n        assertTrue(phaseChanges.isNotEmpty())\n    }\n    \n    @Test\n    fun testInvalidOperationsInDifferentStates() = runTest {\n        val (engine, _) = createTestEngine()\n        \n        // Test pause without active session\n        val pauseResult = engine.pauseSession()\n        assertTrue(pauseResult.isFailure)\n        \n        // Test resume without paused session\n        val resumeResult = engine.resumeSession()\n        assertTrue(resumeResult.isFailure)\n        \n        // Test skip without active session\n        val skipResult = engine.skipToNext()\n        assertTrue(skipResult.isFailure)\n    }\n    \n    @Test\n    fun testSessionCompletion() = runTest {\n        val (engine, mockTimer) = createTestEngine()\n        val config = TimerConfiguration(\n            workDuration = 1,  // Very short durations\n            restDuration = 1,\n            cycles = 1,\n            sets = 1,\n            setBreakDuration = 0,\n            warmupDuration = 0,\n            cooldownDuration = 1\n        )\n        \n        engine.startSession(config)\n        \n        // Advance past total duration\n        val totalDuration = 3000L // 3 seconds total\n        mockTimer.advanceTimeMs(totalDuration)\n        mockTimer.triggerTimerTick()\n        \n        // Session should complete or be near completion\n        // Note: Exact completion depends on implementation details\n        assertTrue(engine.currentSession.value != null)\n    }\n    \n    @Test\n    fun testResetTimer() = runTest {\n        val (engine, mockTimer) = createTestEngine()\n        val config = TimerConfiguration.createStandard()\n        \n        // Start and advance session\n        engine.startSession(config)\n        mockTimer.advanceTimeMs(5000L)\n        mockTimer.triggerTimerTick()\n        \n        // Reset timer\n        val result = engine.resetTimer()\n        \n        assertTrue(result.isSuccess)\n        assertEquals(TimerState.IDLE, engine.timerState.value)\n        assertFalse(engine.isActive.value)\n        assertFalse(mockTimer.isRunning)\n    }\n    \n    @Test\n    fun testSessionIdGeneration() = runTest {\n        val (engine, _) = createTestEngine()\n        val config = TimerConfiguration.createStandard()\n        \n        engine.startSession(config)\n        val session1 = engine.currentSession.value\n        \n        engine.stopSession()\n        engine.startSession(config)\n        val session2 = engine.currentSession.value\n        \n        // Should generate different session IDs\n        assertNotNull(session1)\n        assertNotNull(session2)\n        assertTrue(session1.id != session2.id)\n    }\n    \n    @Test\n    fun testConfigurationValidation() = runTest {\n        val (engine, _) = createTestEngine()\n        \n        // Test various invalid configurations\n        val configs = listOf(\n            TimerConfiguration(\n                workDuration = -1, // Negative duration\n                restDuration = 10,\n                cycles = 1,\n                sets = 1,\n                setBreakDuration = 60\n            ),\n            TimerConfiguration(\n                workDuration = 10,\n                restDuration = 10,\n                cycles = 0, // Zero cycles\n                sets = 1,\n                setBreakDuration = 60\n            ),\n            TimerConfiguration(\n                workDuration = 10,\n                restDuration = 10,\n                cycles = 1,\n                sets = 0, // Zero sets\n                setBreakDuration = 60\n            )\n        )\n        \n        configs.forEach { config ->\n            val result = engine.startSession(config)\n            assertTrue(result.isFailure, \"Expected failure for config: $config\")\n            assertFalse(engine.isActive.value)\n        }\n    }\n}"